155	// free a pointer owned by another thread (page parameter comes first for better codegen)
156	static void mi_decl_noinline mi_free_generic_mt(mi_page_t* page, void* p, bool allow_collect) mi_attr_noexcept {
157	  mi_assert_internal(p!=NULL && page != NULL);
158	  mi_block_t* const block = (mi_page_has_interior_pointers(page) ? _mi_page_ptr_unalign(page, p) : mi_validate_block_from_ptr(page,p));
159	  const bool was_guarded = mi_block_check_unguard(page, block, p);
160	  mi_free_block_mt(page, block, was_guarded, allow_collect);
161	}
