364	// --------------------------------------------------------------------------------------------
365	// `mi_free_try_collect_mt`: Potentially collect a page in a free in an abandoned page.
366	// 1. if the page becomes empty, free it
367	// 2. if it can be reclaimed, reclaim it in our theap
368	// 3. if it went to < 7/8th used, re-abandon to be mapped (so it can be found by theaps looking for free pages)
369	// --------------------------------------------------------------------------------------------
370	
371	// Helper for mi_free_try_collect_mt: free if the page has no more used blocks (this is updated by `_mi_page_free_collect(_partly)`)
372	static bool mi_abandoned_page_try_free(mi_page_t* page)
373	{
374	  if (!mi_page_all_free(page)) return false;
375	  // first remove it from the abandoned pages in the arena (if mapped, this might wait for any readers to finish)
376	  _mi_arenas_page_unabandon(page,NULL);
377	  _mi_arenas_page_free(page,NULL); // we can now free the page directly
378	  return true;
379	}
380	
381	// Helper for mi_free_try_collect_mt: try if we can reabandon a previously abandoned mostly full page to be mapped
382	static bool mi_abandoned_page_try_reabandon_to_mapped(mi_page_t* page)
383	{
384	  // if the page is unmapped, try to reabandon so it can possibly be mapped and found for allocations
385	  // We only reabandon if a full page starts to have enough blocks available to prevent immediate re-abandon of a full page
386	  if (mi_page_is_mostly_used(page)) return false;   // not too full
387	  if (page->memid.memkind != MI_MEM_ARENA || mi_page_is_abandoned_mapped(page)) return false;  // and not already mapped (or unmappable)
388	
389	  mi_assert(!mi_page_is_full(page));
390	  return _mi_arenas_page_try_reabandon_to_mapped(page);
391	}
392	
393	// Release ownership of a page. This may free or reabandoned the page if other blocks are concurrently
394	// freed in the meantime. Returns `true` if the page was freed.
395	// By passing the captured `expected_thread_free`, we can often avoid calling `mi_page_free_collect`.
396	static void mi_abandoned_page_unown_from_free(mi_page_t* page, mi_block_t* expected_thread_free) {
397	  mi_assert_internal(mi_page_is_owned(page));
398	  mi_assert_internal(mi_page_is_abandoned(page));
399	  mi_assert_internal(!mi_page_all_free(page));
400	  // try to cas atomically the original free list (`mt_free`) back with the ownership cleared.
401	  mi_thread_free_t tf_expect = mi_tf_create(expected_thread_free, true);
402	  mi_thread_free_t tf_new    = mi_tf_create(expected_thread_free, false);
403	  while mi_unlikely(!mi_atomic_cas_weak_acq_rel(&page->xthread_free, &tf_expect, tf_new)) {
404	    mi_assert_internal(mi_tf_is_owned(tf_expect));
405	    // while the xthread_free list is not empty..
406	    while (mi_tf_block(tf_expect) != NULL) {
407	      // if there were concurrent updates to the thread-free list, we retry to free or reabandon to mapped (if it became !mosty_used).
408	      _mi_page_free_collect(page,false);  // update used count
409	      if (mi_abandoned_page_try_free(page)) return;
410	      if (mi_abandoned_page_try_reabandon_to_mapped(page)) return;
411	      // otherwise continue un-owning
412	      tf_expect = mi_atomic_load_relaxed(&page->xthread_free);
413	    }
414	    // and try again to release ownership
415	    mi_assert_internal(mi_tf_block(tf_expect)==NULL);
416	    tf_new = mi_tf_create(NULL, false);
417	  }
418	}
